import { Component } from '@angular/core';
import { Location } from '@angular/common';
import { ActivatedRoute } from '@angular/router';
import { WalletModel } from 'src/app/_models';
import { TransactionService, WalletService } from 'src/app/_services';

@Component({
    selector: 'app-transaction-view',
    host: { class: 'childRouteFlex' },
    templateUrl: './transaction-view.component.html',
    styleUrls: ['./transaction-view.component.css']
})
export class TransactionViewComponent {
isEditingTransaction: any;
firstLoad: any;
    constructor(
        public location: Location,
        public transactionService: TransactionService,
        public walletService: WalletService,
        public route: ActivatedRoute
    ) {
        if (walletService.wallets.length == 0)
            walletService.getWalletsFromServer().subscribe();
    }

    selectedTransactionId: number | undefined;
    selectedWallet?: WalletModel;
	isReadOnly: boolean = true;

    ngOnInit(): void {
        this.selectedTransactionId = parseInt(
            this.route.snapshot.paramMap.get('id') ?? '0'
        );

        if (this.transactionService.transactions.length == 0) {
            this.transactionService
                .getTransactionsFromServer(true)
                .subscribe(() => {
                    this.transactionService.selectTransaction(
                        this.selectedTransactionId
                    );
					this.setWalletBySelectedTransaction();
                });
        } else {
            this.transactionService.selectTransaction(
                this.selectedTransactionId
            );
			this.setWalletBySelectedTransaction();
        }
    }

    setSelectedTransactionDate(event: any) {
        if (
            event.target.value != undefined &&
            event.target.value != null &&
            event.target.value != ''
        ) {
            console.log(this.transactionService.selectedTransaction.date);
            this.transactionService.selectedTransaction.date = new Date(
                event.target.value
            );
        }
    }

    selectWallet($event: WalletModel) {
        if ($event.id != undefined && $event.id != null)
            this.transactionService.selectedTransaction.idWallet = $event.id;
    }

	setTransactionType(type: boolean) {
        this.transactionService.selectedTransaction.isIncome = type;
    }

    setTransactionTypeByCheckbox($event: Event) {
        this.setTransactionType(!(<HTMLInputElement>$event.target).checked);
    }

    setWalletBySelectedTransaction() {
        this.selectedWallet = this.walletService.wallets.find(
            (wallet) =>
                wallet.id ==
                this.transactionService.selectedTransaction.idWallet
        );
    }

	editTransaction() {
		this.isReadOnly = false;
	}
}
<div class="component-header">
    <div>
        <i
            class="bi bi-arrow-left-circle pointer"
            [routerLink]="['/transaction']"
            style="cursor: pointer"
        ></i>
        &nbsp;&nbsp;
        <span>{{ this.transactionService.selectedTransaction.name }}</span>
    </div>
    <div class="d-flex align-items-end h-100">
        <app-income-slider
			[readonly]="isReadOnly"
            [isIncome]="this.transactionService.selectedTransaction.isIncome"
            (setTransactionTypeEmitter)="setTransactionType($event)"
        ></app-income-slider>
    </div>
</div>

<div class="mainChild">
    <div class="category-container">
		<div *ngIf="!isReadOnly"
			class="default-badge"
			role="button">
			+
		</div>
        <div
            *ngFor="
                let category of this.transactionService.selectedTransaction
                    .categories
            "
            class="default-badge"
        >
            <span>{{ category.name }}</span>
        </div>
    </div>

    <div class="default-input composed-input primary d-flex">
        <label for="name" class="default-label">Name</label>
        <input
            [readonly]="isReadOnly"
            class="no-style-input inner-input"
            type="text"
            id="name"
            [(ngModel)]="transactionService.selectedTransaction.name"
            placeholder="Transaction Name"
        />
    </div>
    <div class="default-input composed-input primary d-flex">
        <label for="name" class="default-label">Amount</label>
        <input
            [readonly]="isReadOnly"
            class="no-style-input inner-input"
            type="text"
            id="name"
            [(ngModel)]="transactionService.selectedTransaction.amount"
            placeholder="Transaction Name"
        />
    </div>
    <div class="default-input composed-input primary d-flex">
        <label for="name" class="default-label">Date</label>
        <input
            [readonly]="isReadOnly"
            class="no-style-input inner-input"
            type="text"
            id="name"
            [ngModel]="
                transactionService.selectedTransaction.date
                    | date : 'dd/MM/yyyy HH:mm'
            "
            (change)="setSelectedTransactionDate($event)"
            placeholder="Transaction Name"
        />
    </div>
    <div class="default-input composed-input primary d-flex">
        <label for="name" class="default-label">Currency Code</label>
        <input
            [readonly]="isReadOnly"
            class="no-style-input inner-input"
            type="text"
            id="name"
            [(ngModel)]="transactionService.selectedTransaction.currencyCode"
            placeholder="Transaction Name"
        />
    </div>

    <app-dropdown-wallet
        class="dropdown-wallet"
        [readonly]="isReadOnly"
        [selectedWallet]="selectedWallet"
        [wallets]="walletService.wallets"
        (selectWalletEmitter)="selectWallet($event)"
    ></app-dropdown-wallet>
</div>
<!--
<div class="bottom-button">
    <button class="default-button" (click)="editTransaction()">
        Edit Wallet
    </button>
</div> -->

<div
    id="buttonCreate"
    class="default-button bottom-button invert-button"
    ngClass="{{ isEditingTransaction ? 'active' : '' }}"
>
    <div
        class="button-create"
        ngClass="{{
            isEditingTransaction ? 'active' : !firstLoad ? 'off' : ''
        }}"
    >
        <div class="button-create-text secondary">
            <span *ngIf="!isEditingTransaction">Create Transaction</span>
        </div>
    </div>
    <div class="cancel-confirm-container">
        <div
            class="sub-button"
        >
            <span class="income-amount">Cancel</span>
        </div>
        <div
            class="sub-button"
        >
            <span class="expense-amount">Confirm</span>
        </div>
    </div>
</div>
